<template>
  <main class="team-management">
    <div class="management-shell">
      <RouterLink class="back-link" :to="context ? '/team-hub/' + context.team.slug : '/team-hub'">&larr; Back to team</RouterLink>
      <div v-if="loading" class="state-panel" role="status">Loading your team&hellip;</div>
      <p v-if="error" class="feedback feedback-error" role="alert">{{ error }}</p>
      <p v-if="notice" class="feedback feedback-success" role="status">{{ notice }}</p>
      <template v-if="context && !loading">
        <header class="page-header">
          <div class="team-identity"><TeamLogo :src="context.team.logoUrl" :name="context.team.name" :size="64"/><div><p class="eyebrow">TEAM MANAGEMENT</p><h1>{{ context.team.name }}</h1><p class="header-description">Your people. Your lineup. Ready to play.</p></div></div>
          <div class="header-badges"><span v-if="context.team.entitlement?.isPro" class="badge badge-pro">PRO</span><span class="badge" :class="context.team.status === 'ACTIVE' ? 'badge-active' : ''">{{ context.team.status === 'ACTIVE' ? 'Active team' : 'Inactive team' }}</span><span class="access-label">{{ context.teamRole ? roleLabel(context.teamRole) : context.isPlatformAdmin ? 'Administrator' : 'Team access' }}</span></div>
        </header>
        <div class="summary-grid" aria-label="Team at a glance">
          <article><span>Starting lineup</span><strong>{{ startingRoster.length }}<small> / 5</small></strong><div class="capacity-track"><i :style="{ width: Math.min(startingRoster.length / 5, 1) * 100 + '%' }" /></div></article>
          <article><span>Substitutes</span><strong>{{ substituteRoster.length }}<small> / 3</small></strong><div class="capacity-track"><i :style="{ width: Math.min(substituteRoster.length / 3, 1) * 100 + '%' }" /></div></article>
          <article><span>Active members</span><strong>{{ activeMembers.length }}</strong><small>Players and team staff</small></article>
          <article><span>Coach</span><strong class="staff-name">{{ activeCoach?.displayName || 'Not assigned' }}</strong><small>{{ activeCoach ? 'Coach Review access' : 'Assign a coach in Members' }}</small></article>
        </div>
        <nav class="section-nav" aria-label="Management sections"><button v-for="tab in availableTabs" :key="tab.id" type="button" :aria-current="activeTab === tab.id ? 'page' : undefined" :class="{ selected: activeTab === tab.id }" @click="activeTab = tab.id">{{ tab.label }}<span v-if="tab.id === 'members'">{{ activeMembers.length }}</span></button><RouterLink :to="'/team-hub/' + context.team.slug + '/coach-review'" v-if="context.capabilities.canReviewChampionPools">Coach Review &nearr;</RouterLink></nav>

        <div v-if="activeTab === 'roster'" class="section-content">
          <div class="section-heading"><div><p class="eyebrow">MATCH LINEUP</p><h2>Starting five</h2><p>One player per position. Managed by your coach and team management.</p></div><span class="quiet-badge">{{ 5 - startingRoster.length }} open {{ 5 - startingRoster.length === 1 ? 'position' : 'positions' }}</span></div>
          <div class="starter-grid"><article v-for="card in starterCards" :key="card.role" class="position-card" :class="{ vacant: !card.slot }"><div class="position-top"><span class="position-mark">{{ card.role === 'JUNGLE' ? 'JG' : card.role === 'SUPPORT' ? 'SUP' : card.role }}</span><span>{{ roleLabel(card.role) }}</span></div><template v-if="card.slot"><div class="avatar">{{ initials(memberName(card.slot.membershipId)) }}</div><h3>{{ memberName(card.slot.membershipId) }}</h3><p>Starting player</p><button v-if="context.capabilities.canManageRoster" class="text-button" :disabled="submitting" @click="removeSlot(card.slot)">Clear position</button></template><template v-else><div class="vacancy-icon" aria-hidden="true">+</div><h3>Open position</h3><p>Ready for a player</p><button v-if="context.capabilities.canManageRoster" class="text-button" @click="choosePosition(card.role)">Assign player</button></template></article></div>
          <div class="section-heading substitutes-heading"><div><h2>Substitutes <span class="heading-count">{{ substituteRoster.length }}/3</span></h2><p>A maximum of three reserve players for your lineup.</p></div></div>
          <div class="substitute-grid"><article v-for="card in substituteCards" :key="card.position" class="substitute-card" :class="{ vacant: !card.slot }"><div class="avatar avatar-small">{{ card.slot ? initials(memberName(card.slot.membershipId)) : '+' }}</div><div><h3>{{ card.slot ? memberName(card.slot.membershipId) : 'Open substitute spot' }}</h3><p>{{ card.slot ? roleLabel(card.slot.gameRoleKey) : 'Reserve ' + card.position }}</p></div><button v-if="context.capabilities.canManageRoster" class="text-button" :disabled="submitting" @click="card.slot ? removeSlot(card.slot) : choosePosition('TOP', 'SUBSTITUTE')">{{ card.slot ? 'Clear position' : 'Assign' }}</button></article></div>
          <section v-if="context.capabilities.canManageRoster" class="panel assignment-panel"><div class="panel-heading"><h2>Assign a position</h2><p>Choose an existing team player and their place in the lineup.</p></div><form class="roster-form" @submit.prevent="assignSlot"><label>Player<select id="roster-player" v-model="rosterMembershipId" required :disabled="submitting"><option value="" disabled>Select a player</option><option v-for="member in activePlayers" :key="member.id" :value="member.id">{{ member.displayName }}</option></select></label><label>Lineup<select v-model="slotType" :disabled="submitting"><option value="STARTER">Starting five</option><option value="SUBSTITUTE">Substitute</option></select></label><label>Game role<select v-model="gameRole" :disabled="submitting"><option v-for="role in roles" :key="role" :value="role">{{ roleLabel(role) }}</option></select></label><button class="primary-button" :disabled="submitting || !rosterMembershipId || substituteLimitReached">{{ submitting ? 'Saving...' : 'Assign position' }}</button></form><p v-if="substituteLimitReached" class="inline-warning" role="status">All three substitute positions are filled. Clear a position before adding another substitute.</p><p class="help-text">Clearing a position changes the lineup only. To revoke team access, use <button class="inline-link" @click="activeTab = 'members'">Remove from team in Members</button>. Players’ chosen roles do not change the lineup.</p></section>
        </div>

        <TeamStaff v-if="activeTab === 'staff'" :members="activeMembers" :game-key="context.team.gameKey" :can-manage="context.capabilities.canManageMembers" :can-administer="context.capabilities.canAdministerTeam" :submitting="submitting" @assign-coach="assignStaffCoach" @revoke="revokeMember" @settings="activeTab = 'settings'" />
        <TeamPermissions v-if="activeTab === 'permissions'" :team-id="context.team.id" :members="activeMembers" :team-role="context.teamRole" :is-platform-admin="context.isPlatformAdmin" />

        <div v-if="activeTab === 'members'" class="section-content">
          <div class="section-heading"><div><p class="eyebrow">YOUR PEOPLE</p><h2>Team members</h2><p>Active memberships and the access each person has.</p></div></div>
          <section class="panel members-panel"><div class="member-toolbar"><label class="search-label"><span class="sr-only">Search team members</span><input v-model="memberFilter" placeholder="Search team members..." type="search" /></label><label><span class="sr-only">Filter by team role</span><select v-model="memberRoleFilter"><option value="ALL">All roles</option><option value="PLAYER">Players</option><option value="COACH">Coach</option><option value="MANAGER">Manager</option></select></label></div>
            <div class="member-table" role="table" aria-label="Active team memberships"><div class="member-table-head" role="row"><span role="columnheader">Member</span><span role="columnheader">Team role</span><span role="columnheader">Lineup</span><span role="columnheader" class="sr-only">Actions</span></div><div v-for="member in filteredMembers" :key="member.id" class="member-row" role="row"><div class="member-person" role="cell"><span class="avatar avatar-small">{{ initials(member.displayName) }}</span><strong>{{ member.displayName }}<small v-if="member.id === context.myMembershipId">You</small></strong></div><span role="cell"><span class="role-badge">{{ roleLabel(member.role) }}</span></span><span class="assignment-label" role="cell">{{ assignmentLabel(member) }}<small v-if="member.primaryRole" class="playable-roles">Plays {{ [member.primaryRole, ...(member.secondaryRoles || [])].map(roleLabel).join(" / ") }}</small></span><span role="cell" class="member-actions"><button v-if="context.capabilities.canManageMembers && ['PLAYER', 'COACH'].includes(member.role)" class="danger-link" :disabled="submitting" @click="revokeMember(member)">Remove from team</button><button v-else-if="context.capabilities.canAdministerTeam && member.role === 'MANAGER'" class="danger-link" :disabled="submitting" @click="revokeManager(member)">Remove manager</button></span></div></div><p v-if="!filteredMembers.length" class="empty-message">No active members match your search.</p>
          </section>
          <details v-if="context.capabilities.canManageMembers" class="panel add-member-panel"><summary>Add a coach or player <span aria-hidden="true">+</span></summary><div class="details-body"><p class="help-text">Assign an existing account. Adding a player does not assign a lineup position.</p><form v-if="usingIndependentTeamHub" class="member-form" @submit.prevent="assignCandidateMember"><label>Team role<select v-model="memberRole"><option value="COACH">Coach</option><option value="PLAYER">Player</option></select></label><label>Existing account email<input v-model.trim="candidateMemberEmail" type="email" required autocomplete="off" /></label><button class="primary-button" :disabled="submitting">Assign member</button></form><div v-if="usingIndependentTeamHub" class="directory-search"><label>Find an account by email prefix<input v-model.trim="candidateQuery" minlength="2" maxlength="100" /></label><button class="secondary-button" type="button" @click="searchCandidate">Search directory</button><ul><li v-for="account in candidateAccounts" :key="account.subject">{{ account.displayName }}</li></ul><p class="help-text">Use the exact existing email to assign. Directory results do not expose emails.</p></div>
            <form v-else class="member-form" @submit.prevent="saveMember"><label>Team role<select v-model="memberRole" :disabled="submitting"><option value="COACH">Coach</option><option value="PLAYER">Player</option></select></label><div class="account-search"><label>Existing account<input v-model="memberQuery" type="search" autocomplete="off" maxlength="100" role="combobox" aria-autocomplete="list" aria-controls="member-account-results" :aria-expanded="searchOpen" :aria-activedescendant="activeSearchIndex >= 0 ? 'member-result-' + activeSearchIndex : undefined" placeholder="Search username or email" @focus="openSearchResults" @blur="closeSearchResults" @keydown.down.prevent="moveSearchSelection(1)" @keydown.up.prevent="moveSearchSelection(-1)" @keydown.enter.prevent="chooseActiveSearchResult" @keydown.esc="searchOpen = false" /></label><p v-if="memberSearching" class="help-text" role="status">Searching accounts...</p><p v-else-if="memberSearchError" class="inline-warning" role="alert">{{ memberSearchError }}</p><p v-else-if="showNoAccountResults" class="help-text">No matching accounts found.</p><ul v-if="searchOpen && accountResults.length" id="member-account-results" class="account-results" role="listbox"><li v-for="(account,index) in accountResults" :id="'member-result-' + index" :key="account.username" role="option" :aria-selected="activeSearchIndex === index" :class="{ active: activeSearchIndex === index }"><button type="button" :disabled="!account.eligible" @mousedown.prevent @click="selectAccount(account)"><strong>{{ account.displayName }}</strong><span>{{ account.email }} ? {{ account.username }}</span><small v-if="!account.eligible">Account is disabled or unconfirmed</small></button></li></ul></div><button class="primary-button" :disabled="submitting || !selectedAccount?.eligible">{{ submitting ? 'Saving...' : memberRole === 'COACH' && activeCoach ? 'Replace coach' : 'Add member' }}</button><div v-if="selectedAccount" class="selected-account"><span><strong>{{ selectedAccount.displayName }}</strong><small>{{ selectedAccount.email }}</small></span><button class="text-button" type="button" @click="clearSelectedAccount">Clear selection</button></div></form>
          </div></details><p class="help-text membership-note">Removing someone revokes their team access and team-provided benefits. Their account and champion pool are retained.</p>
        </div>

        <div v-if="activeTab === 'settings' && context.capabilities.canAdministerTeam" class="section-content settings-grid">
          <section class="panel"><div class="panel-heading"><h2>Team details</h2><p>Update the name and availability of this team.</p></div><form class="settings-form" @submit.prevent="saveTeam"><label>Team name<input v-model.trim="teamName" required :disabled="submitting" /></label><label>Team status<select v-model="teamStatus" :disabled="submitting"><option value="ACTIVE">Active</option><option value="INACTIVE">Inactive</option></select></label><button class="primary-button" :disabled="submitting">{{ submitting ? 'Saving...' : 'Save details' }}</button></form></section>
          <section class="panel"><div class="panel-heading"><h2>Team manager</h2><p>The manager controls memberships and the team lineup.</p></div><div v-for="manager in activeManagers" :key="manager.id" class="manager-card"><span class="avatar avatar-small">{{ initials(manager.displayName) }}</span><strong>{{ manager.displayName }}</strong><button class="danger-link" :disabled="submitting" @click="revokeManager(manager)">Remove</button></div><p v-if="!activeManagers.length" class="help-text">No manager assigned.</p><form class="settings-form" @submit.prevent="assignManager"><label>Existing manager account email<input v-model.trim="managerEmail" type="email" autocomplete="off" required :disabled="submitting" /></label><button class="secondary-button" :disabled="submitting">{{ submitting ? 'Saving...' : activeManagers.length ? 'Replace manager' : 'Assign manager' }}</button></form></section>
        </div>
        <dialog ref="removalDialog" class="removal-dialog" aria-labelledby="removal-title" @close="pendingRemoval = null"><template v-if="pendingRemoval"><p class="eyebrow">REMOVE TEAM ACCESS</p><h2 id="removal-title">Remove {{ pendingRemoval.member.displayName }}?</h2><p>This removes their {{ pendingRemoval.kind === 'manager' ? 'manager role' : 'membership' }} and team-provided access and benefits. Their account and champion pool will be retained.</p><div class="dialog-actions"><button class="secondary-button" autofocus @click="cancelRemoval">Keep member</button><button class="danger-button" :disabled="submitting" @click="confirmRemoval">Remove from team</button></div></template></dialog>
      </template>
    </div>
  </main>
</template>
<script setup>
import { usingIndependentTeamHub } from '../team-hub/services/migration-mode.mjs';
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { getTeamHub, manageTeamMember, searchAssignableUsers, setTeamManager, setTeamRosterSlot, updateTeam } from './teamHub.service.js';
import { isTeamHubConflict, managerAssignmentInput, memberAssignmentInput, revocationInput } from './teamHub.viewModel.js';
import { nextAccountSearchIndex, normalizeAssignableUser } from './teamAdministration.viewModel.js';
import TeamLogo from './TeamLogo.vue';
import TeamStaff from './TeamStaff.vue';
import TeamPermissions from './TeamPermissions.vue';

const route = useRoute();
const loading = ref(true), error = ref(''), context = ref(null);
const managerEmail = ref(''), memberRole = ref('COACH');
const candidateMemberEmail=ref(''), candidateQuery=ref(''), candidateAccounts=ref([]);
const assignCandidateMember=()=>run(()=>manageTeamMember(memberAssignmentInput(context.value.team,candidateMemberEmail.value,memberRole.value)),()=>{candidateMemberEmail.value='';});
async function searchCandidate(){try{candidateAccounts.value=(await searchAssignableUsers(candidateQuery.value,context.value.team.id)).items;}catch(reason){error.value=reason.message;}}
const memberQuery = ref(''), accountResults = ref([]), selectedAccount = ref(null), memberSearching = ref(false), memberSearchError = ref(''), searchOpen = ref(false), activeSearchIndex = ref(-1);
let searchTimer, searchRequest = 0;
const teamName = ref(''), teamStatus = ref('ACTIVE');
const rosterMembershipId = ref(''), gameRole = ref('TOP'), slotType = ref('STARTER');
const submitting = ref(false);
const roles = ['TOP', 'JUNGLE', 'MID', 'ADC', 'SUPPORT'];
const activePlayers = computed(() => context.value?.members.filter((member) => member.role === 'PLAYER' && member.status === 'ACTIVE') || []);
const activeManagers = computed(() => context.value?.members.filter((member) => member.role === 'MANAGER' && member.status === 'ACTIVE') || []);
const activeCoach = computed(() => context.value?.members.find((member) => member.role === 'COACH' && member.status === 'ACTIVE') || null);
const startingRoster = computed(() => context.value?.roster.filter((slot) => slot.status === 'ACTIVE' && slot.slotType === 'STARTER') || []);
const substituteRoster = computed(() => context.value?.roster.filter((slot) => slot.slotType === 'SUBSTITUTE') || []);
const showNoAccountResults = computed(() => memberQuery.value.trim().length >= 2 && !memberSearching.value && !memberSearchError.value && searchOpen.value && !accountResults.value.length);

async function refresh() { loading.value = true; error.value = ''; try { context.value = await getTeamHub({ teamSlug: route.params.teamSlug }); teamName.value = context.value.team.name; teamStatus.value = context.value.team.status; } catch (reason) { context.value = null; error.value = reason instanceof Error ? reason.message : 'Team Hub access denied'; } finally { loading.value = false; } }
async function run(action, onSuccess) { if (submitting.value) return; notice.value = ''; submitting.value = true; try { await action(); if (onSuccess) onSuccess(); await refresh(); if (context.value) notice.value = 'Changes saved.'; } catch (reason) { const conflict = isTeamHubConflict(reason); await refresh(); error.value = conflict ? 'The team changed. The latest roster is shown; review it and retry your change.' : (reason instanceof Error ? reason.message : 'Team update failed'); } finally { submitting.value = false; } }
const assignManager = () => run(() => setTeamManager(managerAssignmentInput(context.value.team, managerEmail.value)), () => { managerEmail.value = ''; });
const saveTeam = () => run(() => updateTeam({ teamId: context.value.team.id, name: teamName.value, status: teamStatus.value }));
const revokeManager = (manager) => requestRemoval(manager, 'manager');
function clearSelectedAccount() { selectedAccount.value = null; }
function selectAccount(account) { if (!account.eligible) return; selectedAccount.value = account; searchOpen.value = false; activeSearchIndex.value = -1; }
function openSearchResults() { if (memberQuery.value.trim().length >= 2) searchOpen.value = true; }
function closeSearchResults() { setTimeout(() => { searchOpen.value = false; }, 0); }
function moveSearchSelection(direction) { searchOpen.value = true; activeSearchIndex.value = nextAccountSearchIndex(activeSearchIndex.value, direction, accountResults.value.length); }
function chooseActiveSearchResult() { const account = accountResults.value[activeSearchIndex.value]; if (account) selectAccount(account); }
watch(memberQuery, (value) => {
  selectedAccount.value = null; accountResults.value = []; memberSearchError.value = ''; activeSearchIndex.value = -1; searchOpen.value = false;
  clearTimeout(searchTimer); const query = value.trim(); const request = ++searchRequest;
  if (query.length < 2) { memberSearching.value = false; return; }
  memberSearching.value = true;
  searchTimer = setTimeout(async () => { try { const result = await searchAssignableUsers(query, context.value.team.id); if (request !== searchRequest) return; accountResults.value = (result?.items || []).slice(0, 10).map(normalizeAssignableUser); searchOpen.value = true; } catch (reason) { if (request === searchRequest) memberSearchError.value = reason instanceof Error ? reason.message : 'Unable to search accounts.'; } finally { if (request === searchRequest) memberSearching.value = false; } }, 300);
});
const saveMember = async () => { if (!selectedAccount.value?.eligible) return; if (memberRole.value === 'COACH' && activeCoach.value && !window.confirm(`Replace ${activeCoach.value.displayName} as Coach?`)) return; const email = selectedAccount.value.email; await run(() => manageTeamMember(memberAssignmentInput(context.value.team, email, memberRole.value)), () => { memberQuery.value = ''; clearSelectedAccount(); }); };
const revokeMember = (member) => requestRemoval(member, 'member');
const assignStaffCoach = email => {
  if (!context.value?.capabilities.canManageMembers) return;
  if (activeCoach.value && !window.confirm(`Replace ${activeCoach.value.displayName} as Head Coach? This revokes their existing Coach membership.`)) return;
  return run(() => manageTeamMember(memberAssignmentInput(context.value.team, email, 'COACH')));
};
const assignSlot = () => run(() => setTeamRosterSlot({ teamId: context.value.team.id, membershipId: rosterMembershipId.value, gameRoleKey: gameRole.value, slotType: slotType.value, action: 'ASSIGN', expectedRevision: context.value.team.rosterRevision }));
const removeSlot = (slot) => run(() => setTeamRosterSlot({ teamId: context.value.team.id, membershipId: slot.membershipId, gameRoleKey: slot.gameRoleKey, slotType: slot.slotType, action: 'REMOVE', expectedRevision: context.value.team.rosterRevision }));
const memberName = (membershipId) => context.value?.members.find((member) => member.id === membershipId)?.displayName || 'Player';

const activeTab = ref('roster'), memberFilter = ref(''), memberRoleFilter = ref('ALL'), notice = ref('');
const removalDialog = ref(null), pendingRemoval = ref(null);
const activeMembers = computed(() => (context.value?.members || []).filter(m => m.status === 'ACTIVE'));
const filteredMembers = computed(() => activeMembers.value.filter(m => (memberRoleFilter.value === 'ALL' || m.role === memberRoleFilter.value) && (m.displayName || '').toLowerCase().includes(memberFilter.value.trim().toLowerCase())));
const activeRoster = computed(() => (context.value?.roster || []).filter(s => s.status === 'ACTIVE'));
const starterCards = computed(() => roles.map(role => ({ role, slot: activeRoster.value.find(s => s.slotType === 'STARTER' && s.gameRoleKey === role) })));
const substituteCards = computed(() => Array.from({ length: 3 }, (_, i) => ({ position: i + 1, slot: substituteRoster.value[i] })));
const availableTabs = computed(() => [{ id: 'roster', label: 'Roster' }, { id: 'staff', label: 'Coaching & Staff' }, { id: 'permissions', label: 'Permissions' }, { id: 'members', label: 'Members' }, ...(context.value?.capabilities.canAdministerTeam ? [{ id: 'settings', label: 'Settings' }] : [])]);
const selectedIsSubstitute = computed(() => substituteRoster.value.some(s => s.membershipId === rosterMembershipId.value));
const substituteLimitReached = computed(() => slotType.value === 'SUBSTITUTE' && substituteRoster.value.length >= 3 && !selectedIsSubstitute.value);
const roleLabel = role => ({ TOP: 'Top', JUNGLE: 'Jungle', MID: 'Mid', ADC: 'Bot / ADC', SUPPORT: 'Support', MANAGER: 'Manager', COACH: 'Coach', PLAYER: 'Player' }[role] || role);
const initials = name => (name || 'Player').split(/\s+/).filter(Boolean).slice(0, 2).map(x => x[0]).join('').toUpperCase();
const assignmentLabel = member => { const slot = activeRoster.value.find(s => s.membershipId === member.id); return slot ? (slot.slotType === 'STARTER' ? roleLabel(slot.gameRoleKey) + ' starter' : 'Substitute ? ' + roleLabel(slot.gameRoleKey)) : member.role === 'PLAYER' ? 'Not on the lineup' : 'Team staff'; };
function choosePosition(role, type = 'STARTER') { gameRole.value = role; slotType.value = type; nextTick(() => document.querySelector('#roster-player')?.focus()); }
async function requestRemoval(member, kind) { pendingRemoval.value = { member, kind }; await nextTick(); removalDialog.value?.showModal(); }
function cancelRemoval() { removalDialog.value?.close(); pendingRemoval.value = null; }
async function confirmRemoval() { const pending = pendingRemoval.value; if (!pending || submitting.value) return; cancelRemoval(); if (pending.kind === 'manager') await run(() => setTeamManager({ teamId: context.value.team.id, targetMembershipId: pending.member.id, action: 'REVOKE', expectedRevision: context.value.team.membershipRevision })); else await run(() => manageTeamMember(revocationInput(context.value.team, pending.member))); }
onBeforeUnmount(() => { clearTimeout(searchTimer); searchRequest++; });
onMounted(refresh);

</script>

